// v7.10 — references live in refs/. Lazy-load as data URLs on first use.
let MASTER_REFERENCE_DATAURL = '';
let TIPPAN_REFERENCE_DATAURL = '';
const REF_FILES = { MASTER: 'refs/master.jpg', TIPPAN: 'refs/tippan.jpg' };
async function _fetchRefAsDataUrl(path) {
  const r = await fetch(path);
  if (!r.ok) throw new Error(`ref load failed: ${path} ${r.status}`);
  const b = await r.blob();
  return new Promise((res, rej) => { const fr = new FileReader(); fr.onload = () => res(fr.result); fr.onerror = rej; fr.readAsDataURL(b); });
}
async function ensureReferencesLoaded() {
  if (!MASTER_REFERENCE_DATAURL) {
    try { MASTER_REFERENCE_DATAURL = await _fetchRefAsDataUrl(REF_FILES.MASTER); }
    catch (e) { console.warn('master ref load failed', e); }
  }
  if (!TIPPAN_REFERENCE_DATAURL) {
    try { TIPPAN_REFERENCE_DATAURL = await _fetchRefAsDataUrl(REF_FILES.TIPPAN); }
    catch (e) { console.warn('tippan ref load failed', e); }
  }
}
// Kick off the load immediately (non-blocking)
ensureReferencesLoaded();

