let POSE_REFS = {};  // charId -> [dataUrl]

/* v7.9 — IndexedDB shim for reference images (gigabytes of capacity vs localStorage's ~5MB) */
const IDB_NAME = 'kibookal_refs_v1';
const IDB_STORE = 'refs';
let __idbPromise = null;
function idb() {
  if (__idbPromise) return __idbPromise;
  __idbPromise = new Promise((resolve, reject) => {
    try {
      const req = indexedDB.open(IDB_NAME, 1);
      req.onupgradeneeded = () => {
        const db = req.result;
        if (!db.objectStoreNames.contains(IDB_STORE)) db.createObjectStore(IDB_STORE);
      };
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => reject(req.error);
    } catch (e) { reject(e); }
  });
  return __idbPromise;
}
async function idbPut(key, val) {
  try {
    const db = await idb();
    return await new Promise((res, rej) => {
      const tx = db.transaction(IDB_STORE, 'readwrite');
      const store = tx.objectStore(IDB_STORE);
      const r = store.put(val, key);
      r.onsuccess = () => res(true);
      r.onerror = () => rej(r.error);
    });
  } catch (e) { console.warn('[idb] put failed', key, e.message); return false; }
}
async function idbGet(key) {
  try {
    const db = await idb();
    return await new Promise((res, rej) => {
      const tx = db.transaction(IDB_STORE, 'readonly');
      const store = tx.objectStore(IDB_STORE);
      const r = store.get(key);
      r.onsuccess = () => res(r.result);
      r.onerror = () => rej(r.error);
    });
  } catch (e) { console.warn('[idb] get failed', key, e.message); return null; }
}

/* v7.9 — Image compression. Downscale large data URLs to max 1024px JPEG before storage. */
async function compressImageDataUrl(dataUrl, maxDim = 1024, quality = 0.85) {
  if (!dataUrl || typeof dataUrl !== 'string' || !dataUrl.startsWith('data:')) return dataUrl;
  try {
    const img = new Image();
    await new Promise((res, rej) => { img.onload = res; img.onerror = rej; img.src = dataUrl; });
    const longSide = Math.max(img.width, img.height);
    if (longSide <= maxDim && dataUrl.length < 700 * 1024) return dataUrl;
    const scale = Math.min(1, maxDim / longSide);
    const w = Math.round(img.width * scale);
    const h = Math.round(img.height * scale);
    const canvas = document.createElement('canvas');
    canvas.width = w; canvas.height = h;
    const ctx = canvas.getContext('2d');
    ctx.drawImage(img, 0, 0, w, h);
    const compressed = canvas.toDataURL('image/jpeg', quality);
    console.log('[compress]', img.width+'x'+img.height, (dataUrl.length/1024).toFixed(0)+'KB', '→', w+'x'+h, (compressed.length/1024).toFixed(0)+'KB');
    return compressed;
  } catch (e) { console.warn('[compress] failed:', e.message); return dataUrl; }
}

function load(key, fallback) {
  try { const v = localStorage.getItem(key); return v ? JSON.parse(v) : fallback; }
  catch { return fallback; }
}
function save(key, val) {
  try {
    localStorage.setItem(key, JSON.stringify(val));
    return true;
  } catch (e) {
    console.error('[save] localStorage.setItem failed for', key, '-', e.name, e.message);
    if (typeof toast === 'function') toast('⚠ Storage error: ' + (e.message || e.name), 'error');
    return false;
  }
}

/* v7.9 — All data URL references go to IndexedDB (gigabytes of room). LIBRARY only stores
   "idb://id" markers. Compressed to <500KB at upload time. Backward compatible with old
   "lsref://" markers from v7.8 (localStorage). */
async function dehydrateLibraryForSave(lib) {
  const copy = {};
  for (const [charId, c] of Object.entries(lib)) {
    const cc = { ...c };
    if (Array.isArray(c.references)) {
      const out = [];
      for (let idx = 0; idx < c.references.length; idx++) {
        let r = c.references[idx];
        if (typeof r === 'string' && r.startsWith('data:')) {
          // Compress to keep storage humane
          if (r.length > 700 * 1024) {
            try { r = await compressImageDataUrl(r, 1024, 0.85); } catch {}
          }
          const refId = `${charId}_${idx}`;
          const ok = await idbPut('kibookal_ref_' + refId, r);
          if (ok) { out.push('idb://' + refId); }
          else { console.warn('[dehydrate] idb put failed; keeping raw'); out.push(r); }
        } else {
          out.push(r);  // marker, MASTER, TIPPAN, etc.
        }
      }
      cc.references = out;
    }
    copy[charId] = cc;
  }
  return copy;
}

async function hydrateLibrary(lib) {
  for (const c of Object.values(lib || {})) {
    if (!Array.isArray(c.references)) continue;
    const out = [];
    for (const r of c.references) {
      if (typeof r === 'string' && r.startsWith('idb://')) {
        const data = await idbGet('kibookal_ref_' + r.slice(6));
        out.push(data || r);
      } else if (typeof r === 'string' && r.startsWith('lsref://')) {
        // Migrate from v7.8 localStorage refs
        const data = localStorage.getItem('kibookal_ref_' + r.slice(8));
        if (data) {
          const newKey = r.slice(8);
          await idbPut('kibookal_ref_' + newKey, data);
          try { localStorage.removeItem('kibookal_ref_' + newKey); } catch {}
          out.push(data);
        } else { out.push(r); }
      } else { out.push(r); }
    }
    c.references = out;
  }
  return lib;
}

async function loadAll() {
  const lib = load(KEY_LIB, null);
  if (lib && Object.keys(lib).length) LIBRARY = lib;
  else LIBRARY = JSON.parse(JSON.stringify(BUILTIN_CHARACTERS));
  // v7.9: hydrate "idb://" + legacy "lsref://" markers from IndexedDB
  await hydrateLibrary(LIBRARY);
  // ensure built-ins always present (additive)
  for (const [id, c] of Object.entries(BUILTIN_CHARACTERS)) {
    if (!LIBRARY[id]) LIBRARY[id] = JSON.parse(JSON.stringify(c));
  }
  HISTORY = load(KEY_HIST, []);
  SETTINGS = Object.assign(SETTINGS, load(KEY_SETTINGS, {}));
  // Load API keys from the separate tiny store (survives quota issues, overrides settings if newer)
  loadKeys();
  MEMORY = load(KEY_MEMORY, []);
  LIB3D = load(KEY_LIB3D, []);
  STYLE_REFS = load(KEY_STYLE_REF, {});
  POSE_REFS = load(KEY_POSE_REF, {});
  const sst = load(KEY_STATE, null);
  if (sst) Object.assign(STATE, sst);
}
function saveMemory() { save(KEY_MEMORY, MEMORY); }
function saveLib3D() { save(KEY_LIB3D, LIB3D); }
function saveStyleRefs() { save(KEY_STYLE_REF, STYLE_REFS); }
function savePoseRefs() { save(KEY_POSE_REF, POSE_REFS); }
async function saveLibrary() {
  const dehydrated = await dehydrateLibraryForSave(LIBRARY);
  return save(KEY_LIB, dehydrated);
}
function saveHistory() { save(KEY_HIST, HISTORY); }
/* Save API keys separately so they survive even if main settings/storage is full.
   This dedicated tiny key store (~1KB) bypasses the localStorage quota problem. */
function saveKeys() {
  const keys = {
    apiKey: SETTINGS.apiKey || '',
    anthropicKey: SETTINGS.anthropicKey || ''
  };
  try {
    localStorage.setItem(KEY_KEYS, JSON.stringify(keys));
    return true;
  } catch (e) {
    // If even this tiny store fails, aggressively clear non-key state and retry
    console.warn('[saveKeys] storage full — clearing comic pages and retrying');
    try {
      const settingsBackup = localStorage.getItem(KEY_SETTINGS);
      localStorage.removeItem('kibookal_v2_comics');
      localStorage.removeItem('kibookal_v2_state');
      localStorage.setItem(KEY_KEYS, JSON.stringify(keys));
      if (settingsBackup) localStorage.setItem(KEY_SETTINGS, settingsBackup);
      if (typeof toast === 'function') toast('⚠ Storage was full — cleared comic pages to save your API keys', '');
      return true;
    } catch (e2) {
      console.error('[saveKeys] could not save even after cleanup:', e2);
      return false;
    }
  }
}
function loadKeys() {
  try {
    const stored = JSON.parse(localStorage.getItem(KEY_KEYS) || '{}');
    if (stored.apiKey) SETTINGS.apiKey = stored.apiKey;
    if (stored.anthropicKey) SETTINGS.anthropicKey = stored.anthropicKey;
  } catch {}
}

function saveSettings() {
  // Always save keys FIRST in the dedicated tiny store so they persist even if main settings fails
  saveKeys();
  // Then try to save the full settings — if this fails (quota), keys are still safe
  save(KEY_SETTINGS, SETTINGS);
}
/* ============== IndexedDB BLOB STORE — heavy data offloaded from localStorage ==============
   localStorage limit ≈ 5-10 MB per origin. Image data URLs blow past that fast.
   IndexedDB limit ≈ 50% of disk (gigabytes). We store all blob-heavy fields here:
     - comicPages[].image
     - comicCharSheets[name].sheetUrl
     - comicExtraRefs[].dataUrl
     - characterVault entries
     - composed page images
   localStorage keeps only tiny metadata (IDs, statuses, prompts, scores).
   On load, blobs are re-merged into STATE in-memory.
   NOTE: Renamed from IDB_NAME (collided with the older refs DB at line 500) to
   IDB_BLOBS_NAME. Bug fixed 2026-06-04.
*/
const IDB_BLOBS_NAME = 'kibookal_v2_blobs';
const IDB_BLOBS_STORE = 'blobs';
let __idbHandle = null;
function openBlobDB() {
  if (__idbHandle) return Promise.resolve(__idbHandle);
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(IDB_BLOBS_NAME, 1);
    req.onupgradeneeded = (e) => {
      const db = e.target.result;
      if (!db.objectStoreNames.contains(IDB_BLOBS_STORE)) db.createObjectStore(IDB_BLOBS_STORE);
    };
    req.onsuccess = (e) => { __idbHandle = e.target.result; resolve(__idbHandle); };
    req.onerror = (e) => reject(e.target.error);
  });
}
async function idbSet(key, val) {
  try {
    const db = await openBlobDB();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(IDB_BLOBS_STORE, 'readwrite');
      tx.objectStore(IDB_BLOBS_STORE).put(val, key);
      tx.oncomplete = () => resolve(true);
      tx.onerror = (e) => reject(e.target.error);
    });
  } catch (e) { console.warn('[idb] set failed', key, e); return false; }
}
async function idbGet(key) {
  try {
    const db = await openBlobDB();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(IDB_BLOBS_STORE, 'readonly');
      const req = tx.objectStore(IDB_BLOBS_STORE).get(key);
      req.onsuccess = () => resolve(req.result);
      req.onerror = (e) => reject(e.target.error);
    });
  } catch (e) { console.warn('[idb] get failed', key, e); return null; }
}
async function idbDelete(key) {
  try {
    const db = await openBlobDB();
    return new Promise((resolve) => {
      const tx = db.transaction(IDB_BLOBS_STORE, 'readwrite');
      tx.objectStore(IDB_BLOBS_STORE).delete(key);
      tx.oncomplete = () => resolve(true);
      tx.onerror = () => resolve(false);
    });
  } catch { return false; }
}
async function idbClear() {
  try {
    const db = await openBlobDB();
    return new Promise((resolve) => {
      const tx = db.transaction(IDB_BLOBS_STORE, 'readwrite');
      tx.objectStore(IDB_BLOBS_STORE).clear();
      tx.oncomplete = () => resolve(true);
      tx.onerror = () => resolve(false);
    });
  } catch { return false; }
}

// In-memory cascade cache (also persisted to IndexedDB)
window.__cascadeImageCache = window.__cascadeImageCache || {};

// Throttled save — many call sites trigger saveState rapidly. Debounce so we hit
// localStorage at most every 600ms, never blocking the render loop.
let __saveStateTimer = null;
let __saveStatePending = false;

function saveState() {
  __saveStatePending = true;
  if (__saveStateTimer) return; // already scheduled
  __saveStateTimer = setTimeout(() => {
    __saveStateTimer = null;
    if (!__saveStatePending) return;
    __saveStatePending = false;
    saveStateImmediate();
  }, 600);
}

function saveStateImmediate() {
  // Build the slim metadata-only state for localStorage.
  // Strategy: keep references by ID/key only. The actual blobs live in IndexedDB.
  const lite = {
    // Settings + small scalars
    characterId: STATE.characterId,
    poseId: STATE.poseId,
    scenarioKey: STATE.scenarioKey,
    canvas: STATE.canvas,
    customNeg: STATE.customNeg,
    cfg: STATE.cfg,
    seedMode: STATE.seedMode,
    seed: STATE.seed,
    quality: STATE.quality,
    view: STATE.view,
    comicCast: STATE.comicCast,
    comicSpreadMode: STATE.comicSpreadMode,
    comicPageAspect: STATE.comicPageAspect,
    gptImageQuality: STATE.gptImageQuality,
    forceClaudeEnhance: STATE.forceClaudeEnhance,
    scriptCharacterAges: STATE.scriptCharacterAges,
    // Comic pages — strip image data, keep metadata
    comicPages: (STATE.comicPages || []).map((p, i) => ({
      title: p.title,
      pageNum: p.pageNum,
      leftPageNum: p.leftPageNum,
      rightPageNum: p.rightPageNum,
      isSpread: p.isSpread,
      prompt: (p.prompt || '').slice(0, 8000), // cap prompt size too
      status: p.status,
      error: p.error?.slice(0, 240),
      qc: p.qc ? { score: p.qc.score, fix_hint: p.qc.fix_hint?.slice(0, 200) } : null,
      lastRenderCost: p.lastRenderCost,
      imageKey: p.image ? `comic_page_${i}` : null,
      composedKey: p.composed ? `comic_composed_${i}` : null,
      panelCount: (p.panels || []).length,
      panelKeys: (p.panels || []).map((_, j) => p.panels[j].image ? `comic_panel_${i}_${j}` : null)
    })),
    // Comic char sheets — keep description + approved status, blob in IDB
    comicCharSheets: Object.fromEntries(
      Object.entries(STATE.comicCharSheets || {}).map(([name, s]) => [
        name,
        { description: s.description?.slice(0, 4000), approved: !!s.approved, hasSheet: !!s.sheetUrl, sheetKey: s.sheetUrl ? `sheet_${name}` : null }
      ])
    ),
    // Comic extra refs — keep filename + id, blob in IDB
    comicExtraRefs: (STATE.comicExtraRefs || []).map((r, i) => ({
      id: r.id, name: r.name, mediaType: r.mediaType, refKey: r.dataUrl ? `ref_${i}` : null
    })),
    // Character vault metadata only — actual fields in IDB
    characterVaultKeys: Object.keys(STATE.characterVault || {}),
    // Extracted style JSON (small, keep in localStorage)
    comicExtraStyleJson: STATE.comicExtraStyleJson,
    // Master JSON (kept — usually 30-100 KB, fits)
    comicMasterJson: STATE.comicMasterJson,
    // Magazine state (slim similarly)
    magPages: (STATE.magPages || []).map((p, i) => ({
      title: p.title, pageNum: p.pageNum, prompt: p.prompt?.slice(0, 8000), status: p.status,
      pageImageKey: p.pageImage ? `mag_page_${i}` : null,
      zones: (p.zones || []).map((z, j) => ({
        ...z,
        image: null,
        imageKey: z.image ? `mag_zone_${i}_${j}` : null
      }))
    }))
  };

  // Persist blobs to IndexedDB in the background (don't await — fire and forget)
  persistBlobsAsync().catch(e => console.warn('[idb] blob persist failed:', e));

  // Now save the slim metadata to localStorage
  try {
    save(KEY_STATE, lite);
  } catch (e) {
    const isQuota = e.name === 'QuotaExceededError' || /quota/i.test(e.message || '');
    if (isQuota) {
      // Recovery 1: drop the master JSON from the metadata save
      console.warn('[state] quota — dropping master JSON from metadata');
      try {
        const slimmer = { ...lite, comicMasterJson: null };
        save(KEY_STATE, slimmer);
        return;
      } catch {}
      // Recovery 2: drop prompts down to 1000 chars each
      console.warn('[state] quota — slimming prompts further');
      try {
        const slimmest = {
          ...lite,
          comicMasterJson: null,
          comicPages: lite.comicPages.map(p => ({ ...p, prompt: (p.prompt || '').slice(0, 1000) })),
          magPages: lite.magPages.map(p => ({ ...p, prompt: (p.prompt || '').slice(0, 1000) }))
        };
        save(KEY_STATE, slimmest);
        return;
      } catch {}
      // Recovery 3: drop everything except settings + character ID
      console.warn('[state] quota — minimal save (settings only)');
      try {
        save(KEY_STATE, {
          characterId: STATE.characterId, view: STATE.view,
          canvas: STATE.canvas, quality: STATE.quality, customNeg: STATE.customNeg
        });
      } catch (e2) {
        // Total failure — nuke and reset
        try { localStorage.removeItem(KEY_STATE); } catch {}
        console.error('[state] complete save failure — localStorage may be corrupted', e2);
      }
    } else {
      console.warn('[state] save error (non-quota):', e);
    }
  }
}

// === Storage diagnostics + cleanup ===
async function getStorageReport() {
  const report = { localStorage_kb: 0, indexedDB_mb: 'unknown', breakdown: {} };
  try {
    let total = 0;
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      const v = localStorage.getItem(k) || '';
      const size = (k.length + v.length) * 2; // UTF-16 bytes
      total += size;
      report.breakdown[k] = Math.round(size / 1024);
    }
    report.localStorage_kb = Math.round(total / 1024);
  } catch {}
  try {
    if (navigator.storage?.estimate) {
      const est = await navigator.storage.estimate();
      report.indexedDB_mb = Math.round(((est.usage || 0) / 1024 / 1024) * 10) / 10;
      report.quota_mb = Math.round(((est.quota || 0) / 1024 / 1024));
    }
  } catch {}
  return report;
}

// Manual cleanup — exposed to user if they ever want a fresh slate
async function cleanupStorage(level = 'cache') {
  if (level === 'cache') {
    // Clear OLD IndexedDB blobs that are no longer referenced
    const db = await openBlobDB();
    return new Promise(resolve => {
      const tx = db.transaction(IDB_BLOBS_STORE, 'readwrite');
      const store = tx.objectStore(IDB_BLOBS_STORE);
      const req = store.openCursor();
      const validKeys = new Set();
      // Compute all currently-referenced keys
      (STATE.comicPages || []).forEach((p, i) => {
        validKeys.add(`comic_page_${i}`);
        validKeys.add(`comic_composed_${i}`);
        (p.panels || []).forEach((_, j) => validKeys.add(`comic_panel_${i}_${j}`));
      });
      Object.keys(STATE.comicCharSheets || {}).forEach(name => validKeys.add(`sheet_${name}`));
      (STATE.comicExtraRefs || []).forEach((_, i) => validKeys.add(`ref_${i}`));
      let deleted = 0;
      req.onsuccess = (e) => {
        const cursor = e.target.result;
        if (cursor) {
          if (!validKeys.has(cursor.key)) { store.delete(cursor.key); deleted++; }
          cursor.continue();
        } else {
          resolve(deleted);
        }
      };
    });
  } else if (level === 'all') {
    try { localStorage.removeItem(KEY_STATE); } catch {}
    await idbClear();
    return 'all_cleared';
  }
}

// Persist heavy blobs to IndexedDB. Throttled so a 60-page batch doesn't queue
// 60 IDB writes per render.
let __idbPersistTimer = null;
async function persistBlobsAsync() {
  if (__idbPersistTimer) return;
  __idbPersistTimer = setTimeout(async () => {
    __idbPersistTimer = null;
    try {
      // Comic pages
      const pages = STATE.comicPages || [];
      for (let i = 0; i < pages.length; i++) {
        const p = pages[i];
        if (p.image && p.image.startsWith('data:')) {
          await idbSet(`comic_page_${i}`, p.image);
          window.__cascadeImageCache[`comic_page_${i}`] = p.image;
        }
        if (p.composed && p.composed.startsWith('data:')) await idbSet(`comic_composed_${i}`, p.composed);
        for (let j = 0; j < (p.panels || []).length; j++) {
          if (p.panels[j].image?.startsWith('data:')) await idbSet(`comic_panel_${i}_${j}`, p.panels[j].image);
        }
      }
      // Char sheets
      for (const [name, s] of Object.entries(STATE.comicCharSheets || {})) {
        if (s.sheetUrl?.startsWith('data:')) await idbSet(`sheet_${name}`, s.sheetUrl);
      }
      // Refs
      const refs = STATE.comicExtraRefs || [];
      for (let i = 0; i < refs.length; i++) {
        if (refs[i].dataUrl?.startsWith('data:')) await idbSet(`ref_${i}`, refs[i].dataUrl);
      }
    } catch (e) { console.warn('[idb] persist error:', e); }
  }, 1500); // batch up to 1.5s of writes into one transaction sweep
}

// Restore blobs on app boot. Called once during init() before UI paint.
async function restoreBlobsFromIDB() {
  try {
    // Restore comic pages
    const pages = STATE.comicPages || [];
    for (let i = 0; i < pages.length; i++) {
      if (pages[i].imageKey) {
        const blob = await idbGet(pages[i].imageKey);
        if (blob) { pages[i].image = blob; window.__cascadeImageCache[pages[i].imageKey] = blob; }
      }
      if (pages[i].composedKey) {
        const blob = await idbGet(pages[i].composedKey);
        if (blob) pages[i].composed = blob;
      }
      for (let j = 0; j < (pages[i].panelKeys || []).length; j++) {
        if (pages[i].panelKeys[j]) {
          const blob = await idbGet(pages[i].panelKeys[j]);
          if (blob && pages[i].panels?.[j]) pages[i].panels[j].image = blob;
        }
      }
    }
    // Restore sheets
    for (const [name, s] of Object.entries(STATE.comicCharSheets || {})) {
      if (s.sheetKey) {
        const blob = await idbGet(s.sheetKey);
        if (blob) s.sheetUrl = blob;
      }
    }
    // Restore refs
    for (let i = 0; i < (STATE.comicExtraRefs || []).length; i++) {
      if (STATE.comicExtraRefs[i].refKey) {
        const blob = await idbGet(STATE.comicExtraRefs[i].refKey);
        if (blob) STATE.comicExtraRefs[i].dataUrl = blob;
      }
    }
    console.log('[idb] blobs restored from IndexedDB');
  } catch (e) {
    console.warn('[idb] restore failed:', e);
  }
}

function getReferenceDataUrl(refId) {
  if (!refId || typeof refId !== 'string') return '';
  if (refId === 'MASTER') return MASTER_REFERENCE_DATAURL || '';
  if (refId === 'TIPPAN') return TIPPAN_REFERENCE_DATAURL || '';
  // For custom characters, refs are stored as data URLs directly
  return refId.startsWith('data:') ? refId : '';
}

function getCharacterRefDataUrls(charId) {
  const c = LIBRARY[charId]; if (!c) return [];
  const out = [];
  // 1. Character references (highest priority — identity lock)
  for (const r of (c.references || [])) {
    const url = getReferenceDataUrl(r);
    if (url) out.push(url);
  }
  // 2. Style references (aesthetics moodboard)
  for (const r of (STYLE_REFS[charId] || [])) {
    if (r && !out.includes(r)) out.push(r);
  }
  // 3. Pose references (body structure)
  for (const r of (POSE_REFS[charId] || [])) {
    if (r && !out.includes(r)) out.push(r);
  }
  // 4. Auto-include favourited renders as additional refs
  if (SETTINGS.useFavRefs) {
    const favs = HISTORY.filter(h => h.favorite && h.character === charId).slice(0, 3);
    for (const f of favs) if (f.image && !out.includes(f.image)) out.push(f.image);
  }
  return out;
}

function getActiveKey() {
  return (SETTINGS.apiKey && SETTINGS.apiKey.trim()) || EMBEDDED_KEYS[SETTINGS.provider] || '';
}

/* =====================================================
   DOM HELPERS
   ===================================================== */
const $ = (id) => document.getElementById(id);
const $$ = (s, root = document) => Array.from(root.querySelectorAll(s));
function el(tag, attrs = {}, ...children) {
  const e = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (k === 'class') e.className = v;
    else if (k === 'style') e.setAttribute('style', v);
    else if (k.startsWith('on')) e[k] = v;
    else if (k === 'data') for (const [dk, dv] of Object.entries(v)) e.dataset[dk] = dv;
    else if (v !== null && v !== undefined && v !== false) e.setAttribute(k, v);
  }
  for (const ch of children) {
    if (ch === null || ch === undefined) continue;
    if (typeof ch === 'string') e.appendChild(document.createTextNode(ch));
    else e.appendChild(ch);
  }
  return e;
}
function toast(msg, type = '') {
  const t = $('toast');
  t.textContent = msg;
  t.className = 'toast show ' + type;
  setTimeout(() => { t.className = 'toast ' + type; }, 2400);
}

