function characterThumbHTML(charId) {
  const c = LIBRARY[charId];
  if (!c) return charIconSVG(charId);
  // Prefer first reference image if it's a data url
  const firstRef = (c.references || [])[0];
  const url = getReferenceDataUrl(firstRef);
  if (url) return `<img src="${url}" alt="${c.canonical_name}" style="object-fit:cover;width:100%;height:100%;">`;
  return charIconSVG(charId);
}

/* =====================================================
   VIEW SWITCHING
   ===================================================== */
function setView(name) {
  STATE.view = name;
  $$('.tab').forEach(t => t.classList.toggle('active', t.dataset.view === name));
  $$('.view').forEach(v => v.classList.toggle('active', v.id === 'view' + name[0].toUpperCase() + name.slice(1)));
  if (name === 'characters') renderCharactersGrid();
  if (name === 'library') renderLibrary();
  if (name === 'batch') renderBatch();
  if (name === 'compose') renderCompose();
  if (name === 'lab3d') renderLab3d();
  if (name === 'memory') renderMemory();
  if (name === 'upscale') renderUpscaleLab();
  if (name === 'animate') renderAnimateLab();
  if (name === 'lookdev') renderLookdev();
  if (name === 'story') renderStoryView();
  if (name === 'comic') renderComicView();
  if (name === 'magazine') renderMagazineView();
  if (name === 'stylelock') openStyleLockView();
  if (name === 'trigun') { try { initTrigun(); } catch (e) { console.warn('[trigun] init failed:', e); } }
  if (name === 'pageforge') { try { initPageForge(); } catch (e) { console.warn('[pageforge] init failed:', e); } }
  if (name === 'typeset') { try { initTypeset(); } catch (e) { console.warn('[typeset] init failed:', e); } }
  if (name === 'n8n') { renderN8nHistory(); }
  saveState();
}

// Style Lock top-level view — relocate the engine UI here once, init it, paint counts.
let __stylelockRelocated = false;
async function openStyleLockView() {
  try {
    const mount = document.getElementById('stylelockMount');
    const panel = document.getElementById('magViewKBS');
    if (mount && panel && !__stylelockRelocated) {
      panel.style.display = 'block';
      mount.appendChild(panel);   // moves the live node out of Magazine into the new view
      __stylelockRelocated = true;
    } else if (panel) {
      panel.style.display = 'block';
    }
    if (typeof initKBSStyleLock === 'function') await initKBSStyleLock();
    if (typeof _kbsEnsureEngineLoaded === 'function') await _kbsEnsureEngineLoaded();
    const cnt = (typeof KBS_STATE !== 'undefined' && KBS_STATE.engine?.style_bank?.length) || 0;
    const a = document.getElementById('kbsEngineStyleCount'); if (a) a.textContent = cnt;
    const b = document.getElementById('kbsStyleCountLabel'); if (b) b.textContent = cnt;
  } catch (e) { console.warn('[stylelock] open failed:', e); }
}

/* =====================================================
   CINEMATIC PROMPT AUGMENTATION (V4)
   ===================================================== */
function cinematicSuffix() {
  const parts = [];
  if (STATE.cinLighting) parts.push(STATE.cinLighting);
  if (STATE.cinGrade) parts.push(STATE.cinGrade);
  if (STATE.cinLens) parts.push(STATE.cinLens);
  if (STATE.cinAngle) parts.push(STATE.cinAngle);
  if (STATE.cinMood) parts.push(STATE.cinMood);
  if (STATE.cinFinish) parts.push(STATE.cinFinish);
  if (!parts.length) return '';
  return '\n\nCINEMATIC LANGUAGE:\n  - ' + parts.join('\n  - ');
}

/* =====================================================
   UPSCALE LAB
   ===================================================== */
function renderUpscaleLab() {
  const sel = $('upSourceSel');
  sel.innerHTML = '<option value="">— select rendered image —</option>';
  for (const h of HISTORY.slice(0, 30)) {
    sel.appendChild(el('option', { value: h.id }, `${h.characterName || h.character} · ${h.scenarioTitle || h.pose || h.mode || 'render'}`));
  }
  updateUpscaleDims();
}
function updateUpscaleDims() {
  if (!STATE.upSourceUrl) return;
  const img = new Image();
  img.onload = () => { $('upDimensions').textContent = `${img.naturalWidth} × ${img.naturalHeight}px`; };
  img.src = STATE.upSourceUrl;
}
async function runUpscale() {
  if (!STATE.upSourceUrl) { toast('Pick or upload a source image', 'error'); return; }
  if (!getActiveKey()) { toast('Add an API key in ⚙ first.', 'error'); return; }
  const engine = $('upEngine').value;
  const scale = STATE.upTargetScale;
  $('upLoader').classList.add('on');
  $('upRunBtn').disabled = true;
  $('upMeta').textContent = `upscaling ${engine} × ${scale}…`;
  try {
    const body = await buildUpscaleBody(engine, STATE.upSourceUrl, scale, STATE.upPrompt);
    const url = await falCall(`https://fal.run/${engine}`, body);
    const out = url?.image?.url || url?.images?.[0]?.url || url?.upscaled_image?.url || url?.output?.url || url?.url;
    if (!out) throw new Error('no image in response: ' + JSON.stringify(url).slice(0, 200));
    const f = $('upViewer');
    f.classList.remove('empty');
    f.innerHTML = `<img src="${out}" alt="upscaled">`;
    $('upDownloadBtn').disabled = false; $('upDownloadBtn').dataset.url = out;
    $('upSaveBtn').disabled = false; $('upSaveBtn').dataset.url = out;
    $('upCompareBtn').disabled = false;
    STATE.upResultUrl = out;
    $('upMeta').textContent = `upscaled × ${scale} via ${engine.split('/').pop()}`;
    toast('Upscale complete', 'ok');
  } catch (e) { console.error(e); toast('Upscale failed: ' + e.message, 'error'); $('upMeta').textContent = 'upscale failed'; }
  finally { $('upLoader').classList.remove('on'); $('upRunBtn').disabled = false; }
}
async function buildUpscaleBody(engine, imageUrl, scale, prompt) {
  if (engine.includes('clarity')) return { image_url: imageUrl, scale, creativity: 0.35, resemblance: 1.5, prompt: prompt || '' };
  if (engine.includes('creative')) return { image_url: imageUrl, scale, prompt: prompt || 'high quality, detailed' };
  if (engine.includes('aura-sr')) return { image_url: imageUrl, upscaling_factor: scale };
  if (engine.includes('topaz')) return { image_url: imageUrl, upscale_factor: scale };
  if (engine.includes('esrgan')) return { image_url: imageUrl, scale };
  if (engine.includes('recraft')) return { image_url: imageUrl, scale };
  return { image_url: imageUrl, scale };
}
/* ============== FAL.AI API STATUS LAYER (Section 8) ==============
   - Categorized errors: locked / invalid / rate-limited / model-unavailable / network / unknown
   - Preflight ping (lightweight HEAD/POST) before batch operations
   - Persistent banner with queue state + rotate-key action
   - Auto-recovery: detect key change in Settings → re-ping → offer queue resume
*/

const FAL_STATUS = {
  ok: 'ok',
  locked: 'locked',
  invalid: 'invalid',
  rate_limited: 'rate_limited',
  model_unavailable: 'model_unavailable',
  network: 'network',
  unknown: 'unknown'
};

function classifyFalError(status, text) {
  const t = (text || '').toLowerCase();
  if (status === 401) return FAL_STATUS.invalid;
  if (status === 403 && /locked|suspended|exhausted/.test(t)) return FAL_STATUS.locked;
  if (status === 403) return FAL_STATUS.invalid;
  if (status === 404) return FAL_STATUS.model_unavailable;
  if (status === 429) return FAL_STATUS.rate_limited;
  if (status === 0 || status >= 500) return FAL_STATUS.network;
  return FAL_STATUS.unknown;
}

function falErrorMessage(category, raw) {
  const msgs = {
    locked: 'fal.ai key is locked — rotate it in ⚙ Settings.',
    invalid: 'fal.ai key is invalid — paste a fresh key in ⚙ Settings.',
    rate_limited: 'fal.ai is rate-limiting you — will auto-retry with backoff.',
    model_unavailable: 'This model isn\'t available on fal — pick another in the provider dropdown.',
    network: 'Network error reaching fal.ai — check connection.',
    unknown: raw ? raw.slice(0, 240) : 'Unknown fal.ai error'
  };
  return msgs[category] || msgs.unknown;
}

// Show / hide the persistent recovery banner.
function showFalRecoveryBanner(category, pendingCount) {
  let banner = document.getElementById('falRecoveryBanner');
  if (!banner) {
    banner = document.createElement('div');
    banner.id = 'falRecoveryBanner';
    banner.style.cssText = 'position:fixed;top:0;left:0;right:0;z-index:9999;background:linear-gradient(90deg,#7a1f1f,#a23a3a);color:#fff;padding:12px 18px;font-size:13px;display:flex;align-items:center;gap:12px;border-bottom:3px solid #fff;box-shadow:0 4px 18px rgba(0,0,0,.3);font-family:system-ui,sans-serif;';
    document.body.appendChild(banner);
  }
  const message = falErrorMessage(category);
  const pendingNote = pendingCount > 0 ? ` · <b>${pendingCount}</b> pending render${pendingCount===1?'':'s'} preserved` : '';
  banner.innerHTML = `
    <span style="font-size:18px;">⚠</span>
    <span style="flex:1;">${message}${pendingNote}</span>
    <button onclick="(function(){try{document.getElementById('settingsToggle').click();}catch(e){}})()" style="background:#fff;color:#7a1f1f;border:none;padding:6px 14px;border-radius:4px;font-weight:600;cursor:pointer;font-size:12px;">Open Settings</button>
    ${pendingCount > 0 ? `<button onclick="resumePersistedQueue()" style="background:#5a7a44;color:#fff;border:none;padding:6px 14px;border-radius:4px;font-weight:600;cursor:pointer;font-size:12px;">▶ Resume queue</button>` : ''}
    <button onclick="document.getElementById('falRecoveryBanner').remove()" style="background:transparent;color:#fff;border:1px solid rgba(255,255,255,.4);padding:6px 10px;border-radius:4px;cursor:pointer;font-size:11px;">Dismiss</button>
  `;
}

function hideFalRecoveryBanner() {
  const b = document.getElementById('falRecoveryBanner');
  if (b) b.remove();
}

// Persistent queue — survives reloads. Saves: in-progress page IDs + shot IDs that hadn't rendered yet.
const KEY_PENDING_QUEUE = 'kibookal_v2_pending_queue';
function savePendingQueue(queue) {
  try {
    if (!queue || (!queue.comicPageIds?.length && !queue.animateShotIds?.length)) {
      localStorage.removeItem(KEY_PENDING_QUEUE);
      return;
    }
    localStorage.setItem(KEY_PENDING_QUEUE, JSON.stringify(queue));
  } catch (e) { console.warn('[queue] save failed:', e); }
}
function loadPendingQueue() {
  try { return JSON.parse(localStorage.getItem(KEY_PENDING_QUEUE) || 'null'); } catch { return null; }
}
function clearPendingQueue() { try { localStorage.removeItem(KEY_PENDING_QUEUE); } catch {} }

// Snapshot the current state of all in-flight work into the persistent queue.
// Called when a key-locked / invalid error happens mid-batch.
function snapshotPendingWork() {
  const queue = { ts: Date.now(), comicPageIds: [], animateShotIds: [] };
  // Comic pages that are pending / rendering / failed (i.e. NOT ready)
  if (Array.isArray(STATE.comicPages)) {
    queue.comicPageIds = STATE.comicPages
      .filter(p => p.status !== 'ready' && p.prompt)
      .map(p => p.title || String(STATE.comicPages.indexOf(p)));
  }
  // Animate shots that haven't rendered yet
  const proj = STATE.animateProject;
  if (proj?.shots?.length) {
    queue.animateShotIds = proj.shots
      .filter(s => !proj.clips?.[s.shot_id]?.videoUrl)
      .map(s => s.shot_id);
  }
  savePendingQueue(queue);
  return queue;
}

// Resume button on the banner calls this.
window.resumePersistedQueue = async function () {
  const queue = loadPendingQueue();
  if (!queue) { toast('No pending queue to resume', 'info'); hideFalRecoveryBanner(); return; }
  // Re-ping the key first — silently abort if it's still bad.
  const status = await pingFalApi();
  if (status !== FAL_STATUS.ok) {
    toast('fal.ai key still bad — rotate it first', 'error');
    return;
  }
  hideFalRecoveryBanner();
  toast(`▶ Resuming ${(queue.comicPageIds.length + queue.animateShotIds.length)} pending render${queue.comicPageIds.length + queue.animateShotIds.length === 1 ? '' : 's'}…`, 'info');
  // Resume comic page renders
  for (const title of queue.comicPageIds) {
    const page = STATE.comicPages?.find(p => (p.title || String(STATE.comicPages.indexOf(p))) === title);
    if (page && typeof renderComicFullPage === 'function') {
      try { await renderComicFullPage(page); } catch (e) { console.warn('[resume] page failed:', e); }
    }
  }
  // Resume animate shot renders
  for (const shotId of queue.animateShotIds) {
    if (typeof renderOneShot === 'function') {
      try { await renderOneShot(shotId); } catch (e) { console.warn('[resume] shot failed:', e); }
    }
  }
  clearPendingQueue();
  toast('✓ Queue resumed', 'ok');
};

// Lightweight ping. Uses a tiny known-good request to test the current key.
async function pingFalApi() {
  const key = getActiveKey();
  if (!key) return FAL_STATUS.invalid;
  try {
    // Use a HEAD against fal.run (no body, no cost). Some endpoints reject HEAD; fall back to a tiny POST.
    const res = await fetch('https://fal.run/fal-ai/fast-sdxl', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Key ' + key },
      body: JSON.stringify({ prompt: 'ping', num_inference_steps: 1, num_images: 1 })
    });
    if (res.ok || res.status === 422) {
      // 422 = validation error on body, but key was accepted. Good signal.
      hideFalRecoveryBanner();
      return FAL_STATUS.ok;
    }
    const text = await res.text();
    const cat = classifyFalError(res.status, text);
    console.warn(`[fal-ping] status=${res.status} cat=${cat}: ${text.slice(0, 200)}`);
    if (cat === FAL_STATUS.locked || cat === FAL_STATUS.invalid) {
      const q = loadPendingQueue();
      showFalRecoveryBanner(cat, (q?.comicPageIds?.length || 0) + (q?.animateShotIds?.length || 0));
    }
    return cat;
  } catch (e) {
    console.warn('[fal-ping] network error:', e);
    return FAL_STATUS.network;
  }
}

async function falCall(url, body, opts = {}) {
  const retries = opts.retries ?? 2;
  for (let attempt = 0; attempt <= retries; attempt++) {
    let res;
    try {
      res = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': 'Key ' + getActiveKey() },
        body: JSON.stringify(body)
      });
    } catch (netErr) {
      // Pure network error — retry with backoff
      if (attempt < retries) {
        await new Promise(r => setTimeout(r, 1500 * (attempt + 1)));
        continue;
      }
      throw new Error('Network error reaching fal.ai — check connection');
    }
    if (res.status === 429 && attempt < retries) {
      await new Promise(r => setTimeout(r, 2000 * (attempt + 1)));
      continue;
    }
    if (!res.ok) {
      const t = await res.text();
      const cat = classifyFalError(res.status, t);
      // === Studio-grade error handling ===
      if (cat === FAL_STATUS.locked || cat === FAL_STATUS.invalid) {
        // 1. Snapshot the queue so we can resume after key rotation
        const queue = snapshotPendingWork();
        const pendingCount = queue.comicPageIds.length + queue.animateShotIds.length;
        // 2. Show persistent banner (replaces the one-shot toast)
        showFalRecoveryBanner(cat, pendingCount);
        throw new Error(falErrorMessage(cat));
      }
      if (cat === FAL_STATUS.rate_limited) {
        throw new Error(falErrorMessage(cat));
      }
      if (cat === FAL_STATUS.model_unavailable) {
        throw new Error(falErrorMessage(cat) + ' Raw: ' + t.slice(0, 120));
      }
      throw new Error(`${res.status}: ${t.slice(0, 240)}`);
    }
    return await res.json();
  }
  throw new Error('falCall: retries exhausted');
}

/* ============== CANONICAL NEGATIVE ENFORCEMENT (§6) ============== */
function appendCanonicalNegative(prompt, customNeg) {
  let p = prompt || '';
  // Strip any prior NEGATIVE block to avoid duplication
  p = p.replace(/\n*NEGATIVE[^\n]*:[\s\S]*?(?=\n\n|$)/, '').trimEnd();
  let neg = CANONICAL_NEGATIVE;
  if (customNeg && customNeg.trim()) {
    neg += '\nADDITIONAL: ' + customNeg.trim();
  }
  return p + '\n\n' + neg;
}

/* ============== REFERENCE-MODE ROUTING (§1.2) ============== */
// STATE.refMode: 'auto' | 'force_edit' | 'force_base' | 'kontext'
function resolveProviderRoute(providerId, refs) {
  const cfg = PROVIDER_MODELS[providerId];
  if (!cfg) return null;
  const hasCharRefs = (refs || []).length > 0;
  const refMode = STATE.refMode || 'auto';
  if (refMode === 'kontext') {
    return { ...PROVIDER_MODELS.fal_kontext_pro, providerId: 'fal_kontext_pro', useEdit: true };
  }
  let useEdit = false;
  if (cfg.alwaysEdit) useEdit = true;
  else if (refMode === 'force_edit') useEdit = !!cfg.edit;
  else if (refMode === 'force_base') useEdit = false;
  else /* auto */ useEdit = hasCharRefs && !!cfg.edit;
  return { ...cfg, providerId, useEdit };
}

/* =====================================================
   ANIMATE LAB
   ===================================================== */
function renderAnimateLab() {
  const sel = $('anSourceSel');
  if (sel) {
    sel.innerHTML = '<option value="">— select rendered image —</option>';
    for (const h of HISTORY.slice(0, 30)) {
      sel.appendChild(el('option', { value: h.id }, `${h.characterName || h.character} · ${h.scenarioTitle || h.pose || h.mode || 'render'}`));
    }
  }
  // Wire the new Film Project Mode on first entry (idempotent — uses event listeners that are re-added safely)
  try { wireAnimateProjectMode(); } catch (e) { console.warn('[animate] project mode wire failed:', e); }
}
async function runAnimate() {
  if (!STATE.anSourceUrl) { toast('Pick or upload a source image', 'error'); return; }
  if (!getActiveKey()) { toast('Add an API key in ⚙ first.', 'error'); return; }
  const engine = $('anEngine').value;
  const duration = parseInt($('anDuration').value) || 5;
  const aspect = $('anAspect').value;
  const prompt = $('anPrompt').value;
  $('anLoader').classList.add('on');
  $('anRunBtn').disabled = true;
  $('anMeta').textContent = `animating via ${engine.split('/').slice(-2).join('/')}…`;
  try {
    const body = buildAnimateBody(engine, STATE.anSourceUrl, prompt, duration, aspect);
    const data = await falCall(`https://fal.run/${engine}`, body);
    const videoUrl = data?.video?.url || data?.output?.video?.url || data?.videos?.[0]?.url || data?.url;
    if (!videoUrl) throw new Error('no video in response: ' + JSON.stringify(data).slice(0, 200));
    const f = $('anViewer');
    f.classList.remove('empty');
    f.innerHTML = `<video src="${videoUrl}" controls autoplay loop style="width:100%;height:100%;object-fit:contain;"></video>`;
    f.dataset.aspect = aspect;
    $('anDownloadBtn').disabled = false; $('anDownloadBtn').dataset.url = videoUrl;
    $('anSaveBtn').disabled = false; $('anSaveBtn').dataset.url = videoUrl;
    STATE.anResultUrl = videoUrl;
    $('anMeta').textContent = `video ready · ${duration}s · ${engine.split('/').slice(-2).join('/')}`;
    toast('Animation complete', 'ok');
  } catch (e) { console.error(e); toast('Animate failed: ' + e.message, 'error'); $('anMeta').textContent = 'animation failed'; }
  finally { $('anLoader').classList.remove('on'); $('anRunBtn').disabled = false; }
}
function buildAnimateBody(engine, imageUrl, prompt, duration, aspect) {
  const body = { image_url: imageUrl, prompt: prompt || 'subtle camera push-in, gentle character motion, ambient particles drifting', duration: String(duration) };
  if (engine.includes('kling')) body.aspect_ratio = aspect;
  if (engine.includes('luma')) body.aspect_ratio = aspect;
  if (engine.includes('veo3')) body.aspect_ratio = aspect;
  return body;
}

/* =========================================================================
   FILM PROJECT MODE — Animate Lab v2 · Phase 1
   Comic pages → Claude story bible → Claude shot list → fal video render
   Phase 2 (next): voice/sfx/music → auto-edit → FFmpeg final mix
   ========================================================================= */

// Video model pricing per second (US$)
const VIDEO_PROVIDER_PRICING = {
  'fal-ai/veo3/image-to-video':                            { perSec: 0.50, label: 'Veo 3' },
  'fal-ai/kling-video/v2.1/master/image-to-video':         { perSec: 0.35, label: 'Kling 2.1 Master' },
  'fal-ai/runway-gen3/turbo/image-to-video':               { perSec: 0.25, label: 'Runway Gen-3 Turbo' },
  'fal-ai/kling-video/v2.1/standard/image-to-video':       { perSec: 0.15, label: 'Kling 2.1 Standard' },
  'fal-ai/luma-dream-machine/ray-2/image-to-video':        { perSec: 0.18, label: 'Luma Ray 2' },
  'fal-ai/minimax/video-01-live/image-to-video':           { perSec: 0.10, label: 'Minimax Hailuo' },
  'fal-ai/wan-i2v':                                        { perSec: 0.05, label: 'Wan I2V' },
  'fal-ai/pika/v2.2/image-to-video':                       { perSec: 0.08, label: 'Pika 2.2' }
};

// Initialize the project state container in STATE if missing
function ensureAnimateProject() {
  if (!STATE.animateProject) {
    STATE.animateProject = {
      sourceType: null, // 'comic_state' | 'upload_pdf' | 'upload_zip' | 'upload_images'
      pages: [],        // [{ id, idx, imageDataUrl, prompt, title, aspect }]
      bible: null,      // story_bible.json
      shots: [],        // shot cards
      clips: {},        // shotId → { videoUrl, status, error, attempts, cost }
      settings: {
        engine: 'fal-ai/kling-video/v2.1/master/image-to-video',
        shotLen: 5,
        aspect: '16:9',
        autoQC: true
      }
    };
  }
  return STATE.animateProject;
}

// ── 1 · INGEST ──────────────────────────────────────────────────────────────
function setAnProjectStatus(text, color = 'ash') {
  const el = $('anProjectStatus');
  if (el) { el.innerHTML = text; el.style.color = `var(--${color})`; }
}

function setAnProjectMeta(text) {
  const el = $('anProjectMeta');
  if (el) el.textContent = text;
}

async function ingestFromComicState() {
  const proj = ensureAnimateProject();
  const comicPages = (STATE.comicPages || []).filter(p => p.image);
  if (!comicPages.length) {
    setAnProjectStatus('✗ No rendered comic pages in the Comic tab yet. Go to Comic, render some pages, then come back.', 'red');
    return false;
  }
  proj.sourceType = 'comic_state';
  proj.pages = comicPages.map((p, i) => ({
    id: `p${String(i + 1).padStart(3, '0')}`,
    idx: i + 1,
    imageDataUrl: p.image,
    prompt: p.prompt || '',
    title: p.title || `Page ${i + 1}`,
    aspect: p.isSpread ? '16:9' : '9:16'
  }));
  setAnProjectStatus(`✓ Loaded <b>${proj.pages.length}</b> pages from the Comic tab.`, 'green');
  paintProjectThumbs();
  paintProjectDashboard();
  saveState && saveState();
  return true;
}

async function ingestFromUpload(files) {
  if (!files || !files.length) return false;
  const proj = ensureAnimateProject();
  proj.sourceType = 'upload_images';
  proj.pages = [];

  // Convert each file to data URL (compressed to keep storage sane)
  const imageFiles = Array.from(files).filter(f => /^image\//.test(f.type));
  if (!imageFiles.length) {
    setAnProjectStatus('✗ Upload at least one image (PDF/ZIP parsing ships with Phase 2).', 'red');
    return false;
  }

  setAnProjectStatus(`Loading ${imageFiles.length} image${imageFiles.length===1?'':'s'}…`, 'saffron');
  for (let i = 0; i < imageFiles.length; i++) {
    const f = imageFiles[i];
    const dataUrl = await new Promise((resolve, reject) => {
      const r = new FileReader();
      r.onload = () => resolve(r.result);
      r.onerror = reject;
      r.readAsDataURL(f);
    });
    // Compress (Nano-Banana-style helper, already in app)
    const compressed = await compressRefForNano(dataUrl, 1536, 0.88).catch(() => dataUrl);
    proj.pages.push({
      id: `u${String(i + 1).padStart(3, '0')}`,
      idx: i + 1,
      imageDataUrl: compressed,
      prompt: '',
      title: f.name.replace(/\.[^.]+$/, ''),
      aspect: '16:9'
    });
  }
  setAnProjectStatus(`✓ Loaded <b>${proj.pages.length}</b> uploaded image${proj.pages.length===1?'':'s'}.`, 'green');
  paintProjectThumbs();
  paintProjectDashboard();
  saveState && saveState();
  return true;
}

function paintProjectThumbs() {
  const wrap = $('anProjectThumbs');
  if (!wrap) return;
  const proj = ensureAnimateProject();
  if (!proj.pages.length) { wrap.style.display = 'none'; return; }
  wrap.style.display = 'grid';
  wrap.innerHTML = proj.pages.slice(0, 24).map(p =>
    `<img src="${p.imageDataUrl}" title="${escapeHtml(p.title)}" style="width:100%;aspect-ratio:1;object-fit:cover;border:1px solid var(--line);border-radius:3px;">`
  ).join('');
  if (proj.pages.length > 24) {
    wrap.insertAdjacentHTML('beforeend', `<div style="grid-column:1/-1;text-align:center;font-size:11px;color:var(--ash);padding:4px;">… +${proj.pages.length - 24} more pages</div>`);
  }
}

function paintProjectDashboard() {
  const proj = ensureAnimateProject();
  const dash = $('anProjectDashboard');
  const meta = $('anProjectMeta');
  if (!dash) return;
  if (!proj.pages.length) {
    dash.style.display = 'none';
    if (meta) meta.textContent = 'No project loaded · pick a comic source above to begin.';
    return;
  }
  dash.style.display = 'block';
  if (meta) meta.textContent = `Project · ${proj.pages.length} pages · ${proj.shots.length} shots · ${proj.bible ? 'bible ✓' : 'no bible yet'}`;
  $('anStatPages').textContent = proj.pages.length;
  $('anStatShots').textContent = proj.shots.length;
  const totalDuration = proj.shots.reduce((s, sh) => s + (sh.duration_sec || 0), 0);
  $('anStatDuration').textContent = totalDuration ? `${Math.round(totalDuration)}s` : '0s';

  // Bible summary
  const bibleBox = $('anBibleSummary');
  if (bibleBox) {
    if (proj.bible) {
      bibleBox.style.display = 'block';
      const b = proj.bible;
      bibleBox.innerHTML = `
        <div style="font-family:'Cinzel',serif;font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:var(--saffron);margin-bottom:6px;">Story bible</div>
        <div><b>Genre:</b> ${escapeHtml(b.genre || '—')}</div>
        <div><b>Tone:</b> ${escapeHtml(b.tone || '—')}</div>
        <div><b>Pacing:</b> ${escapeHtml(b.pacing || '—')}</div>
        <div><b>Music style:</b> ${escapeHtml(b.music_style || '—')}</div>
        <div><b>Edit style:</b> ${escapeHtml(b.edit_style || '—')}</div>
        <div><b>Color grade:</b> ${escapeHtml(b.color_grade || '—')}</div>
      `;
    } else {
      bibleBox.style.display = 'none';
    }
  }

  // Shot grid
  const grid = $('anShotGrid');
  if (grid) {
    grid.innerHTML = '';
    for (const shot of proj.shots) {
      const clip = proj.clips[shot.shot_id] || {};
      const page = proj.pages.find(p => p.id === shot.source_page_id) || proj.pages[shot.page_idx - 1];
      const card = el('div', { class: 'shot-card', style: 'border:1px solid var(--line);border-radius:6px;padding:8px;background:var(--paper);' });
      const statusBadge = clip.status === 'ready' ? '<span style="color:var(--green);">✓ rendered</span>'
        : clip.status === 'rendering' ? '<span style="color:var(--saffron);">⟳ rendering…</span>'
        : clip.status === 'failed' ? '<span style="color:var(--red);">✗ failed</span>'
        : '<span style="color:var(--ash);">queued</span>';
      card.innerHTML = `
        <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:6px;">
          <span style="font-family:'Cinzel',serif;font-size:11px;letter-spacing:.1em;">${escapeHtml(shot.shot_id || '?')}</span>
          <span style="font-size:10px;">${statusBadge}</span>
        </div>
        ${clip.videoUrl
          ? `<video src="${clip.videoUrl}" controls muted loop style="width:100%;border-radius:3px;aspect-ratio:16/9;object-fit:cover;background:#000;"></video>`
          : (page?.imageDataUrl ? `<img src="${page.imageDataUrl}" style="width:100%;aspect-ratio:16/9;object-fit:cover;border-radius:3px;">` : '')
        }
        <div style="font-size:10.5px;color:var(--ash);margin-top:6px;line-height:1.3;">
          <div><b>Beat:</b> ${escapeHtml(shot.emotional_beat || '—')}</div>
          <div><b>Motion:</b> ${escapeHtml((shot.motion || '').slice(0, 80))}…</div>
          <div><b>Length:</b> ${shot.duration_sec || '?'}s</div>
        </div>
        ${clip.status === 'failed' ? `<div style="font-size:10px;color:var(--red);margin-top:4px;">${escapeHtml((clip.error||'').slice(0,80))}</div>` : ''}
        <div style="display:flex;gap:4px;margin-top:6px;">
          ${clip.videoUrl ? `<button class="btn sm" data-shot-download="${shot.shot_id}">⬇</button>` : ''}
          <button class="btn sm ghost" data-shot-render="${shot.shot_id}">${clip.videoUrl ? '↻ regen' : '⚡ render'}</button>
        </div>
      `;
      grid.appendChild(card);
    }
    // Wire per-shot buttons
    grid.querySelectorAll('[data-shot-render]').forEach(b => b.onclick = (e) => {
      const id = e.target.dataset.shotRender;
      renderOneShot(id);
    });
    grid.querySelectorAll('[data-shot-download]').forEach(b => b.onclick = (e) => {
      const id = e.target.dataset.shotDownload;
      downloadShotClip(id);
    });
  }

  // Enable export buttons
  const anyClips = Object.values(proj.clips).some(c => c?.videoUrl);
  $('anDownloadAllClipsBtn').disabled = !anyClips;
  $('anExportShotsJsonBtn').disabled = !proj.shots.length;
  $('anRenderAllBtn').disabled = !proj.shots.length;

  // Update cost estimate
  updateAnimateCostEstimate();
}

function updateAnimateCostEstimate() {
  const proj = ensureAnimateProject();
  const est = $('anProjectCostEstimate');
  if (!est) return;
  if (!proj.shots.length) {
    est.textContent = 'Cost estimate appears after shot list is built.';
    return;
  }
  const engine = $('anProjectEngine')?.value || proj.settings.engine;
  const perSec = VIDEO_PROVIDER_PRICING[engine]?.perSec || 0.30;
  const totalSec = proj.shots.reduce((s, sh) => s + (sh.duration_sec || 5), 0);
  const cost = totalSec * perSec;
  est.innerHTML = `<b>${proj.shots.length}</b> shots · <b>${Math.round(totalSec)}s</b> total · ≈ <b>$${cost.toFixed(2)}</b> at <b>${VIDEO_PROVIDER_PRICING[engine]?.label || engine}</b>.`;
}

// ── 2 · STORY BIBLE (Claude) ───────────────────────────────────────────────
async function generateStoryBible() {
  const proj = ensureAnimateProject();
  if (!proj.pages.length) { toast('Load pages first', 'error'); return; }
  const claudeKey = (typeof SETTINGS !== 'undefined' && SETTINGS.anthropicKey) || (typeof EMBEDDED_KEYS !== 'undefined' && EMBEDDED_KEYS.anthropic) || '';
  if (!claudeKey) { toast('Claude API key required (⚙ Settings)', 'error'); return; }
  const statusEl = $('anBibleStatus');
  if (statusEl) statusEl.innerHTML = `🧠 Claude is reading <b>${proj.pages.length}</b> pages…`;

  // Send up to 12 sample pages (compressed) to keep the request reasonable
  const sample = proj.pages.length <= 12 ? proj.pages : [
    ...proj.pages.slice(0, 6),
    ...proj.pages.slice(Math.floor(proj.pages.length / 2) - 2, Math.floor(proj.pages.length / 2) + 2),
    ...proj.pages.slice(-4)
  ];

  // Compress each sample image to ~768px so Claude vision request stays light
  const compressedSamples = await Promise.all(sample.map(async (p) => {
    const dataUrl = await compressRefForNano(p.imageDataUrl, 768, 0.78).catch(() => p.imageDataUrl);
    const m = dataUrl.match(/^data:(.*?);base64,(.*)$/);
    return { mediaType: m?.[1] || 'image/jpeg', base64: m?.[2] || '', title: p.title, idx: p.idx, prompt: (p.prompt || '').slice(0, 600) };
  }));

  const sys = `You are an Oscar-winning film director + sound designer + editor analyzing an illustrated comic book to plan a short animated film adaptation.

You will receive a SAMPLE of the comic's pages (images + their original generation prompts). From these, infer the COMPLETE story bible that every later stage of the animation pipeline will follow.

Output STRICT JSON only, matching this schema:

{
  "title": "<inferred film title>",
  "genre": "<primary genre + sub-genre, e.g. 'warm-hearted Indian folk adventure with mystery beats'>",
  "tone": "<2-4 adjectives, e.g. 'playful, mischievous, nostalgic, gentle'>",
  "pacing": "<patient | balanced | brisk | breakneck — plus 1 sentence why>",
  "target_duration_minutes": <number — total film length estimate>,
  "emotional_arc": ["beat 1", "beat 2", "beat 3", "beat 4"],
  "main_characters": [
    { "name": "<name>", "voice_brief": "<age + accent + emotional register, e.g. 'curious 11yr boy, light Marathi accent, eager and bright'>" }
  ],
  "music_style": "<specific instrumentation + mood + tempo, e.g. 'soft tabla + bansuri flute + harmonium, 70-90 BPM, warm afternoon mood'>",
  "music_cues": [
    { "name": "intro_theme", "description": "...", "duration_s": 20 },
    { "name": "mischief_motif", "description": "...", "duration_s": 8 },
    { "name": "tender_resolution", "description": "...", "duration_s": 30 }
  ],
  "edit_style": "<one paragraph on cut rhythm, transition types, hold-on-faces preference, etc.>",
  "color_grade": "<specific palette / film stock vocabulary>",
  "sound_design_notes": "<distinctive sfx environment, e.g. 'temple bells, parrot calls, sandals on slate, sizzle of ghee'>",
  "negative_directions": ["no jump scares", "no synth music", "no English dialogue beyond simple exclamations"]
}

Be SPECIFIC and CINEMATIC. This bible drives every render, every voice, every sfx, every cut. Generic answers waste the brief.`;

  const userContent = [
    ...compressedSamples.map(s => ({ type: 'image', source: { type: 'base64', media_type: s.mediaType, data: s.base64 } })),
    { type: 'text', text: `These are ${compressedSamples.length} sample pages from a ${proj.pages.length}-page comic.\n\nPage titles/prompts:\n${compressedSamples.map(s => `[${s.idx}] ${s.title}${s.prompt ? ' — ' + s.prompt.slice(0, 200) : ''}`).join('\n')}\n\nGenerate the complete story bible JSON for the animated film adaptation.` }
  ];

  try {
    const body = {
      model: SETTINGS.claudeModel || 'claude-sonnet-4-5',
      max_tokens: 3000,
      system: sys,
      messages: [{ role: 'user', content: userContent }]
    };
    const res = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'x-api-key': claudeKey, 'anthropic-version': '2023-06-01', 'anthropic-dangerous-direct-browser-access': 'true' },
      body: JSON.stringify(body)
    });
    if (!res.ok) throw new Error(`Claude ${res.status}: ${(await res.text()).slice(0, 240)}`);
    const j = await res.json();
    let text = (j?.content?.[0]?.text || '').trim();
    text = text.replace(/^```(?:json)?\s*/, '').replace(/\s*```$/, '').trim();
    const bible = JSON.parse(text);
    proj.bible = bible;
    const jsonEl = $('anBibleJson'); if (jsonEl) jsonEl.value = JSON.stringify(bible, null, 2);
    const detailsEl = $('anBibleDetails'); if (detailsEl) detailsEl.style.display = '';
    if (statusEl) statusEl.innerHTML = `✓ Bible ready · <b>${bible.title || 'untitled'}</b> · ${escapeHtml(bible.genre || '')}`;
    toast(`Story bible: "${bible.title || 'untitled'}"`, 'ok');
    paintProjectDashboard();
    saveState && saveState();
  } catch (e) {
    console.error('[bible]', e);
    if (statusEl) statusEl.innerHTML = `✗ ${escapeHtml(e.message || 'failed')}`;
    toast(`Bible failed: ${e.message}`, 'error');
  }
}

// ── 3 · SHOT LIST (Claude) ──────────────────────────────────────────────────
async function generateShotList() {
  const proj = ensureAnimateProject();
  if (!proj.pages.length) { toast('Load pages first', 'error'); return; }
  if (!proj.bible) { toast('Generate the story bible first', 'error'); return; }
  const claudeKey = (typeof SETTINGS !== 'undefined' && SETTINGS.anthropicKey) || (typeof EMBEDDED_KEYS !== 'undefined' && EMBEDDED_KEYS.anthropic) || '';
  if (!claudeKey) { toast('Claude API key required', 'error'); return; }

  const shotLen = parseInt($('anShotLen')?.value) || 5;
  const aspect = $('anProjectAspect')?.value || '16:9';
  proj.settings.shotLen = shotLen;
  proj.settings.aspect = aspect;

  const statusEl = $('anShotsStatus');
  if (statusEl) statusEl.innerHTML = `📋 Claude is designing <b>${proj.pages.length}</b> shots…`;

  // Chunk pages into batches of 20 so prompts stay small
  const BATCH = 20;
  proj.shots = [];

  const sys = `You are an Oscar-winning film editor planning the shot list for an animated film adapted from an illustrated comic book.

You will receive the STORY BIBLE (genre, tone, pacing, music style, edit style) plus a list of comic PAGES (title + prompt). For each page, design ONE shot card describing the camera motion, length, dialogue/narration, sfx cues, transition out, and emotional beat.

Output STRICT JSON only — an array of shot cards, in story order:

[
  {
    "shot_id": "p001_s01",
    "page_idx": 1,
    "source_page_id": "<page id matching the input>",
    "duration_sec": ${shotLen},
    "motion": "<concrete camera + subject motion, e.g. 'slow push-in on Aarav's face from medium to close-up, his eyebrows raise as he spots the empty pot, subtle dust motes drifting in afternoon light'>",
    "emotional_beat": "<one or two words, e.g. 'curiosity', 'realization', 'mischief'>",
    "narration": "<short narrator line, or empty string>",
    "dialogue": [ { "speaker": "<character>", "line": "<short line>" } ],
    "sfx_cues": ["<concrete sfx description>", "..."],
    "music_cue": "<one of the music_cues from the bible, or 'silence'>",
    "transition_out": "<gentle dissolve | hard cut | match cut | fade to black | wipe>",
    "notes": "<editor's note, max 200 chars>"
  }
]

Rules:
- Default duration = ${shotLen}s, but vary ±2s based on the emotional beat (long holds on tender moments, quick on mischief).
- The motion descriptions are READ BY a video-generation AI — be CONCRETE and PHYSICAL. Avoid "feel" words. Say what the camera and subject literally do.
- Dialogue should be sparse and natural — short lines a kid would actually say. Use the character voices from the bible.
- Match the music_cue and edit pace from the bible.
- aspect: ${aspect}
- ONE shot per page (no fragmenting).`;

  try {
    for (let i = 0; i < proj.pages.length; i += BATCH) {
      const batch = proj.pages.slice(i, i + BATCH);
      const userText = `STORY BIBLE:\n${JSON.stringify(proj.bible, null, 2)}\n\nPAGES (${i + 1}–${i + batch.length} of ${proj.pages.length}):\n${batch.map(p => `[${p.id}] page ${p.idx}: ${p.title}${p.prompt ? '\n  prompt: ' + p.prompt.slice(0, 400) : ''}`).join('\n\n')}\n\nGenerate the JSON shot list for ONLY these ${batch.length} pages, in order. shot_id format: p<idx zero-padded to 3>_s01`;
      const body = {
        model: SETTINGS.claudeModel || 'claude-sonnet-4-5',
        max_tokens: 6000,
        system: sys,
        messages: [{ role: 'user', content: userText }]
      };
      const res = await fetch('https://api.anthropic.com/v1/messages', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'x-api-key': claudeKey, 'anthropic-version': '2023-06-01', 'anthropic-dangerous-direct-browser-access': 'true' },
        body: JSON.stringify(body)
      });
      if (!res.ok) throw new Error(`Claude ${res.status}: ${(await res.text()).slice(0, 240)}`);
      const j = await res.json();
      let text = (j?.content?.[0]?.text || '').trim();
      text = text.replace(/^```(?:json)?\s*/, '').replace(/\s*```$/, '').trim();
      const batchShots = JSON.parse(text);
      if (!Array.isArray(batchShots)) throw new Error('Claude did not return an array');
      proj.shots.push(...batchShots);
      if (statusEl) statusEl.innerHTML = `📋 Designed <b>${proj.shots.length}</b>/<b>${proj.pages.length}</b> shots…`;
      paintProjectDashboard();
    }
    if (statusEl) statusEl.innerHTML = `✓ Shot list ready · <b>${proj.shots.length}</b> shots · ${Math.round(proj.shots.reduce((s,sh)=>s+(sh.duration_sec||0),0))}s total`;
    toast(`Shot list: ${proj.shots.length} shots designed`, 'ok');
    paintProjectDashboard();
    saveState && saveState();
  } catch (e) {
    console.error('[shots]', e);
    if (statusEl) statusEl.innerHTML = `✗ ${escapeHtml(e.message || 'failed')}`;
    toast(`Shot list failed: ${e.message}`, 'error');
  }
}

// ── 4 · RENDER per-shot video ──────────────────────────────────────────────
async function renderOneShot(shotId) {
  const proj = ensureAnimateProject();
  const shot = proj.shots.find(s => s.shot_id === shotId);
  if (!shot) { toast('Shot not found', 'error'); return; }
  const page = proj.pages.find(p => p.id === shot.source_page_id) || proj.pages[shot.page_idx - 1];
  if (!page) { toast(`No source page for ${shotId}`, 'error'); return; }
  if (!getActiveKey()) { toast('Add fal API key in ⚙ Settings', 'error'); return; }

  const engine = $('anProjectEngine')?.value || proj.settings.engine;
  const aspect = $('anProjectAspect')?.value || proj.settings.aspect;
  const duration = Math.max(3, Math.min(10, Math.round(shot.duration_sec || 5)));

  proj.clips[shotId] = { ...(proj.clips[shotId] || {}), status: 'rendering', error: null };
  paintProjectDashboard();

  // Build the motion prompt from shot card
  const motionPrompt = `${shot.motion || 'subtle camera push-in, gentle ambient motion'}.\n\nEmotional beat: ${shot.emotional_beat || 'observational'}.\n\nKeep characters' faces, costumes, and props EXACTLY as they appear in the source still — zero drift.`;

  try {
    const body = buildAnimateBody(engine, page.imageDataUrl, motionPrompt, duration, aspect);
    const data = await falCall(`https://fal.run/${engine}`, body, { retries: 1 });
    const videoUrl = data?.video?.url || data?.output?.video?.url || data?.videos?.[0]?.url || data?.url;
    if (!videoUrl) throw new Error('No video URL in response');
    proj.clips[shotId] = {
      videoUrl,
      status: 'ready',
      error: null,
      attempts: (proj.clips[shotId]?.attempts || 0) + 1,
      cost: (VIDEO_PROVIDER_PRICING[engine]?.perSec || 0.30) * duration
    };
    if (typeof trackRenderCost === 'function') {
      trackRenderCost({ title: shotId }, engine, { enhance: false, qc: false });
    }
    paintProjectDashboard();
    saveState && saveState();
    return videoUrl;
  } catch (e) {
    console.error('[shot]', shotId, e);
    proj.clips[shotId] = { ...(proj.clips[shotId] || {}), status: 'failed', error: e.message };
    paintProjectDashboard();
    throw e;
  }
}

async function renderAllShots() {
  const proj = ensureAnimateProject();
  if (!proj.shots.length) { toast('Generate shot list first', 'error'); return; }

  // === Section 8A · Preflight API status check ===
  toast('🔌 Checking fal.ai key…', 'info');
  const apiStatus = await pingFalApi();
  if (apiStatus !== FAL_STATUS.ok) {
    toast(`✗ Cannot start render: ${falErrorMessage(apiStatus)}`, 'error');
    return;
  }
  const progressEl = $('anRenderProgress');
  if (progressEl) progressEl.style.display = 'block';
  const totalEl = $('anRenderTotal'); if (totalEl) totalEl.textContent = proj.shots.length;
  const doneEl = $('anRenderDone');
  const barEl = $('anRenderBar');
  const etaEl = $('anRenderEta');

  // Render in parallel batches of 3 (fal handles concurrency, but limit to avoid 429)
  const CONCURRENCY = 3;
  const startTime = Date.now();
  let completed = 0;

  const queue = proj.shots.filter(s => !proj.clips[s.shot_id]?.videoUrl);
  if (!queue.length) { toast('All shots already rendered. Use ↻ regen on individual cards to redo.', 'ok'); return; }

  const updateProgress = () => {
    if (doneEl) doneEl.textContent = completed;
    if (barEl) barEl.style.width = `${(completed / queue.length) * 100}%`;
    const elapsed = (Date.now() - startTime) / 1000;
    const remaining = completed ? (elapsed / completed) * (queue.length - completed) : 0;
    if (etaEl) etaEl.textContent = remaining ? `≈ ${Math.round(remaining)}s remaining` : '—';
  };

  toast(`🎬 Rendering ${queue.length} shots…`, 'info');

  // Simple worker pool
  let nextIdx = 0;
  const workers = Array.from({ length: CONCURRENCY }, async () => {
    while (true) {
      const my = nextIdx++;
      if (my >= queue.length) return;
      try {
        await renderOneShot(queue[my].shot_id);
      } catch (e) {
        // already logged + status set in renderOneShot
      }
      completed++;
      updateProgress();
    }
  });
  await Promise.all(workers);

  toast(`✓ Render pass complete · ${completed} shots`, 'ok');
  paintProjectDashboard();
  if (progressEl) setTimeout(() => { progressEl.style.display = 'none'; }, 3000);
}

// ── Downloads ──────────────────────────────────────────────────────────────
async function downloadShotClip(shotId) {
  const proj = ensureAnimateProject();
  const clip = proj.clips[shotId];
  if (!clip?.videoUrl) { toast('No video yet', 'error'); return; }
  try {
    const r = await fetch(clip.videoUrl);
    const blob = await r.blob();
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = `${shotId}.mp4`;
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(a.href), 1000);
  } catch (e) { toast(`Download failed: ${e.message}`, 'error'); }
}

async function downloadAllClipsZip() {
  const proj = ensureAnimateProject();
  if (typeof JSZip === 'undefined') { toast('JSZip not loaded', 'error'); return; }
  const ready = Object.entries(proj.clips).filter(([_, c]) => c?.videoUrl);
  if (!ready.length) { toast('No rendered clips yet', 'error'); return; }
  toast(`📦 Packaging ${ready.length} clips…`, 'info');
  const zip = new JSZip();
  const folder = zip.folder('film_clips');
  for (const [shotId, clip] of ready) {
    try {
      const r = await fetch(clip.videoUrl);
      const blob = await r.blob();
      folder.file(`${shotId}.mp4`, blob);
    } catch (e) {
      console.warn(`Skipped ${shotId}:`, e);
    }
  }
  // Bundle shot list + bible
  if (proj.bible) zip.file('story_bible.json', JSON.stringify(proj.bible, null, 2));
  zip.file('shot_list.json', JSON.stringify(proj.shots, null, 2));
  const blob = await zip.generateAsync({ type: 'blob' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  const ts = new Date().toISOString().replace(/[:T.]/g, '-').slice(0, 19);
  a.download = `kibookal_film_${ts}.zip`;
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(a.href), 1000);
  toast(`✓ ZIP ready · ${ready.length} clips`, 'ok');
}

function exportShotListJson() {
  const proj = ensureAnimateProject();
  if (!proj.shots.length) { toast('No shot list yet', 'error'); return; }
  const data = { bible: proj.bible, shots: proj.shots, generated: new Date().toISOString() };
  const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `kibookal_shot_list_${Date.now()}.json`;
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(a.href), 1000);
}

function resetAnimateProject() {
  if (!confirm('Clear the entire film project — pages, bible, shot list, and rendered clips? This cannot be undone.')) return;
  STATE.animateProject = null;
  ensureAnimateProject();
  setAnProjectStatus('No project loaded yet.', 'ash');
  paintProjectThumbs();
  paintProjectDashboard();
  saveState && saveState();
  toast('Project reset', 'ok');
}

// ── Mode toggle (Project / Single / Batch) + initial wiring ────────────────
function wireAnimateProjectMode() {
  // Mode tabs
  const setMode = (mode) => {
    $('anModeProject').classList.toggle('active', mode === 'project');
    $('anModeSingle').classList.toggle('active', mode === 'single');
    $('anModeBatch').classList.toggle('active', mode === 'batch');
    $('anViewProject').style.display = mode === 'project' ? '' : 'none';
    $('anViewSingle').style.display = mode === 'single' ? '' : 'none';
    $('anViewBatch').style.display = mode === 'batch' ? '' : 'none';
  };
  $('anModeProject')?.addEventListener('click', () => setMode('project'));
  $('anModeSingle')?.addEventListener('click', () => setMode('single'));
  $('anModeBatch')?.addEventListener('click', () => setMode('batch'));

  // Source picker — show/hide upload input
  const srcSel = $('anProjectSource');
  const upload = $('anProjectUpload');
  if (srcSel && upload) {
    srcSel.onchange = () => {
      const v = srcSel.value;
      upload.style.display = v === 'comic_state' ? 'none' : '';
      if (v === 'upload_pdf') upload.accept = '.pdf';
      else if (v === 'upload_zip') upload.accept = '.zip';
      else if (v === 'upload_images') upload.accept = 'image/*';
    };
    srcSel.dispatchEvent(new Event('change'));
  }

  // Ingest button
  $('anProjectIngestBtn')?.addEventListener('click', async () => {
    const src = srcSel?.value || 'comic_state';
    if (src === 'comic_state') {
      await ingestFromComicState();
    } else {
      if (!upload.files?.length) {
        upload.click();
        upload.onchange = async () => { if (upload.files?.length) await ingestFromUpload(upload.files); };
        return;
      }
      await ingestFromUpload(upload.files);
    }
  });

  // Bible button
  $('anBuildBibleBtn')?.addEventListener('click', generateStoryBible);

  // Shot list button
  $('anBuildShotsBtn')?.addEventListener('click', generateShotList);

  // Engine change → re-paint cost
  $('anProjectEngine')?.addEventListener('change', updateAnimateCostEstimate);

  // Render all
  $('anRenderAllBtn')?.addEventListener('click', renderAllShots);

  // Downloads + reset
  $('anDownloadAllClipsBtn')?.addEventListener('click', downloadAllClipsZip);
  $('anExportShotsJsonBtn')?.addEventListener('click', exportShotListJson);
  $('anProjectResetBtn')?.addEventListener('click', resetAnimateProject);

  // Initial paint
  ensureAnimateProject();
  paintProjectThumbs();
  paintProjectDashboard();
}

