function renderLab3d() {
  const sel = $('lab3dSourceSel');
  sel.innerHTML = '<option value="">— select rendered image —</option>';
  for (const h of HISTORY.slice(0, 30)) {
    sel.appendChild(el('option', { value: h.id }, `${h.characterName || h.character} · ${h.scenarioTitle || h.pose || h.mode || 'render'}`));
  }
  // Library
  const lib = $('lab3dLibrary');
  lib.innerHTML = '';
  if (!LIB3D.length) {
    lib.innerHTML = '<div style="grid-column:1 / -1;font-family:Caveat,cursive;color:var(--ash);font-size:13px;text-align:center;padding:14px;">3D models you save will appear here</div>';
    return;
  }
  for (const m of LIB3D) {
    const item = el('div', { class: 'lib-item', onclick: () => load3DModel(m.url, m.label) });
    item.innerHTML = `
      <img src="${m.thumb || ''}" style="background:#222;" alt="">
      <div class="lib-meta">
        <div class="lib-name">${m.label}</div>
        <div class="lib-pose">${m.model || 'glb'}</div>
      </div>
    `;
    lib.appendChild(item);
  }
}

function load3DModel(url, label) {
  const viewer = $('lab3dViewer');
  viewer.classList.remove('empty');
  viewer.innerHTML = `<model-viewer src="${url}" alt="${label || '3D model'}" camera-controls auto-rotate auto-rotate-delay="500" exposure="1" shadow-intensity="0.7" environment-image="neutral" style="width:100%;height:100%;background:#1a1a1a;"></model-viewer>`;
  STATE.lab3dResultUrl = url;
  $('lab3dDownloadBtn').disabled = false;
  $('lab3dDownloadBtn').dataset.url = url;
  $('lab3dSaveBtn').disabled = false;
  $('lab3dResetCamBtn').disabled = false;
  $('lab3dMeta').textContent = `model loaded · ${label || 'untitled'}`;
}

async function runLab3D() {
  let imageUrl = STATE.lab3dSourceUrl;
  if (!imageUrl) { toast('Pick or upload a 2D image first', 'error'); return; }
  if (!getActiveKey()) { toast('Add an API key in ⚙ first.', 'error'); return; }
  const model = STATE.lab3dModel;
  const url = `https://fal.run/${model}`;
  const body = {};
  const quality = STATE.lab3dQuality || 'medium';
  if (model.includes('hunyuan3d/v21') || model.includes('hunyuan3d-v21')) {
    body.input_image_url = imageUrl;
    body.textured_mesh = STATE.lab3dTexture;
    body.remove_background = STATE.lab3dRemoveBg;
    body.num_inference_steps = quality === 'high' ? 75 : quality === 'fast' ? 30 : 50;
    body.guidance_scale = 7.5;
    body.octree_resolution = quality === 'high' ? 512 : 384;
  } else if (model.includes('hunyuan3d')) {
    body.input_image_url = imageUrl;
    body.textured_mesh = STATE.lab3dTexture;
    body.remove_background = STATE.lab3dRemoveBg;
    body.num_inference_steps = quality === 'high' ? 75 : 50;
    body.octree_resolution = quality === 'high' ? 512 : 384;
  } else if (model.includes('trellis')) {
    body.image_url = imageUrl;
    body.ss_sampling_steps = quality === 'high' ? 25 : 12;
    body.slat_sampling_steps = quality === 'high' ? 25 : 12;
    body.mesh_simplify = quality === 'high' ? 0.95 : 0.9;
    body.texture_size = quality === 'high' ? 2048 : 1024;
  } else if (model.includes('triposr')) {
    body.image_url = imageUrl;
  } else if (model.includes('tripo3d')) {
    body.image_url = imageUrl;
    body.style = 'object';
    body.quad = false;
    body.texture = STATE.lab3dTexture;
    body.pbr = STATE.lab3dTexture;
  } else if (model.includes('rodin')) {
    body.input_image_urls = [imageUrl];
    body.geometry_file_format = STATE.lab3dFormat || 'glb';
    body.material = STATE.lab3dTexture ? 'PBR' : 'Shaded';
    body.quality = quality === 'high' ? 'high' : quality === 'fast' ? 'medium' : 'medium';
    body.use_hyper = quality === 'high';
  }
  $('lab3dLoader').classList.add('on');
  $('lab3dRunBtn').disabled = true;
  $('lab3dMeta').textContent = `generating ${model}…`;
  try {
    const res = await fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json', 'Authorization': 'Key ' + getActiveKey() }, body: JSON.stringify(body) });
    if (!res.ok) throw new Error(`${res.status}: ${(await res.text()).slice(0, 240)}`);
    const data = await res.json();
    // Find a GLB / mesh URL in the response (different models return different shapes)
    const meshUrl =
      data?.model_mesh?.url ||
      data?.model_glb?.url ||
      data?.mesh?.url ||
      data?.output?.url ||
      data?.glb?.url ||
      (Array.isArray(data?.meshes) ? data.meshes[0]?.url : null) ||
      data?.url;
    if (!meshUrl) throw new Error('no mesh URL in response: ' + JSON.stringify(data).slice(0, 200));
    load3DModel(meshUrl, `3D · ${new Date().toLocaleTimeString()}`);
    toast('3D model generated', 'ok');
  } catch (err) {
    console.error(err); toast('3D failed: ' + err.message, 'error');
    $('lab3dMeta').textContent = '3D generation failed';
  } finally {
    $('lab3dLoader').classList.remove('on');
    $('lab3dRunBtn').disabled = false;
  }
}

/* =====================================================
   MEMORY (Workflow recipes)
   ===================================================== */
/* =====================================================
   n8n WORKFLOW RUNNER
   ===================================================== */
const KEY_N8N_HISTORY = 'kibookal_v5_n8n_history';
let N8N_HISTORY = load(KEY_N8N_HISTORY, []);
function saveN8nHistory() { save(KEY_N8N_HISTORY, N8N_HISTORY); }

async function runN8nWorkflow(kind) {
  const cfg = kind === 'kit_maker'
    ? { hook: $('kmWebhook').value, loaderId: 'kmLoader', btnId: 'kmRunBtn', label: 'Kit Maker',
        body: () => ({
          kit_name: $('kmKitName').value,
          age_group: $('kmAgeGroup').value,
          kit_brief: $('kmKitBrief').value,
          link_references: $('kmLinks').value.split('\n').map(s => s.trim()).filter(Boolean),
          has_images: $('kmHasImages').classList.contains('on')
        }),
        required: ['kit_name'] }
    : { hook: $('drWebhook').value, loaderId: 'drLoader', btnId: 'drRunBtn', label: 'Deep Research',
        body: () => ({
          research_topic: $('drTopic').value,
          research_depth: $('drDepth').value,
          research_brief: $('drBrief').value,
          link_references: $('drLinks').value.split('\n').map(s => s.trim()).filter(Boolean)
        }),
        required: ['research_topic'] };

  if (!cfg.hook) { toast('Paste a webhook URL for ' + cfg.label, 'error'); return; }
  const body = cfg.body();
  for (const k of cfg.required) if (!body[k]) { toast(`Field "${k}" is required`, 'error'); return; }

  $(cfg.loaderId).classList.add('on');
  $(cfg.btnId).disabled = true;
  $('n8nDocMeta').textContent = `· running ${cfg.label}…`;
  $('n8nPreview').innerHTML = `<div class="empty-state" style="padding:80px 20px;"><div class="es-h">Running ${cfg.label}…</div>The two LLM agents are running in parallel. This typically takes 60–240 seconds.</div>`;
  try {
    const res = await fetch(cfg.hook, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
    if (!res.ok) throw new Error('HTTP ' + res.status + ': ' + (await res.text()).slice(0, 240));
    // n8n form-trigger returns HTML or text by default; webhook variant returns JSON. Try both.
    const contentType = res.headers.get('content-type') || '';
    let raw, html;
    if (contentType.includes('application/json')) {
      const data = await res.json();
      // Common shapes: { markdown: "...", html: "..." } or { output: "..." } or just a string
      raw = data?.markdown || data?.output || data?.text || data?.content || data?.result || JSON.stringify(data, null, 2);
      html = data?.html || markdownToHtml(raw);
    } else {
      const text = await res.text();
      // If the server returned HTML, use that. Otherwise treat as markdown.
      if (text.trim().startsWith('<')) { html = text; raw = htmlToMarkdown(text); }
      else { raw = text; html = markdownToHtml(raw); }
    }
    showN8nResult({
      kind, label: cfg.label, when: new Date().toISOString(),
      input: body, raw, html,
      title: body.kit_name || body.research_topic || cfg.label
    });
    toast(`${cfg.label} complete`, 'ok');
  } catch (err) {
    console.error(err);
    toast(`${cfg.label} failed: ${err.message}`, 'error');
    $('n8nPreview').innerHTML = `<div class="empty-state" style="padding:80px 20px;color:var(--red);"><div class="es-h">Run failed</div>${escapeHtml(err.message)}</div>`;
    $('n8nDocMeta').textContent = '· run failed';
  } finally {
    $(cfg.loaderId).classList.remove('on');
    $(cfg.btnId).disabled = false;
  }
}

function showN8nResult(run) {
  STATE.n8nLastRun = run;
  $('n8nPreview').innerHTML = run.html || markdownToHtml(run.raw || '');
  $('n8nDocMeta').textContent = `· ${run.label} · ${run.title}`;
  ['n8nCopyMarkdown','n8nCopyText','n8nCopyHtml','n8nDownloadMd','n8nDownloadTxt','n8nDownloadHtml'].forEach(id => { const e = $(id); if (e) e.disabled = false; });
  N8N_HISTORY.unshift({ id: 'n8n_' + Date.now(), kind: run.kind, title: run.title, when: run.when, raw: run.raw, html: run.html, input: run.input });
  if (N8N_HISTORY.length > 30) N8N_HISTORY.length = 30;
  saveN8nHistory();
  renderN8nHistory();
}

function renderN8nHistory() {
  const wrap = $('n8nHistory'); if (!wrap) return;
  wrap.innerHTML = '';
  if (!N8N_HISTORY.length) { wrap.innerHTML = '<div style="font-family:\'Caveat\',cursive;color:var(--ash);font-size:13px;text-align:center;padding:10px;">no runs yet</div>'; return; }
  N8N_HISTORY.forEach(h => {
    const row = el('div', {
      style: 'padding:6px 8px;border-radius:4px;cursor:pointer;font-size:12px;background:var(--paper-2);display:flex;align-items:center;gap:6px;',
      onclick: () => showN8nResult(h)
    });
    row.innerHTML = `<span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:${h.kind === 'kit_maker' ? 'var(--saffron)' : 'var(--gold)'};"></span><span style="flex:1;font-weight:500;">${escapeHtml(h.title)}</span><span style="opacity:0.6;font-size:10px;">${new Date(h.when).toLocaleString()}</span>`;
    wrap.appendChild(row);
  });
}

function switchN8nView(mode) {
  if (!STATE.n8nLastRun) return;
  $('n8nViewRendered').style.background = mode === 'rendered' ? 'var(--saffron)' : '';
  $('n8nViewRendered').style.color = mode === 'rendered' ? 'white' : '';
  $('n8nViewRaw').style.background = mode === 'raw' ? 'var(--saffron)' : '';
  $('n8nViewRaw').style.color = mode === 'raw' ? 'white' : '';
  if (mode === 'raw') $('n8nPreview').innerHTML = `<pre style="font-family:'JetBrains Mono',monospace;font-size:12px;white-space:pre-wrap;color:var(--ink);background:var(--paper);padding:14px;border-radius:4px;">${escapeHtml(STATE.n8nLastRun.raw || '')}</pre>`;
  else $('n8nPreview').innerHTML = STATE.n8nLastRun.html || markdownToHtml(STATE.n8nLastRun.raw || '');
}

function downloadN8nDoc(format) {
  if (!STATE.n8nLastRun) return;
  const r = STATE.n8nLastRun;
  let content, mime, ext;
  if (format === 'md') { content = r.raw || ''; mime = 'text/markdown'; ext = 'md'; }
  else if (format === 'txt') { content = (r.raw || '').replace(/[#*_`>]/g, '').replace(/\[([^\]]+)\]\([^)]*\)/g, '$1'); mime = 'text/plain'; ext = 'txt'; }
  else { content = wrapHtmlDoc(r.title, r.html || markdownToHtml(r.raw || '')); mime = 'text/html'; ext = 'html'; }
  const blob = new Blob([content], { type: mime + ';charset=utf-8' });
  const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = `${(r.title || 'output').replace(/[^a-z0-9]+/gi,'_')}.${ext}`; a.click();
}

// Minimal markdown → HTML (good enough for n8n outputs)
function markdownToHtml(md) {
  if (!md) return '';
  let html = String(md);
  // Escape HTML
  html = html.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  // Code blocks
  html = html.replace(/```([\s\S]*?)```/g, (_, c) => `<pre><code>${c}</code></pre>`);
  // Headings
  html = html.replace(/^###### (.*)$/gm, '<h6>$1</h6>');
  html = html.replace(/^##### (.*)$/gm, '<h5>$1</h5>');
  html = html.replace(/^#### (.*)$/gm, '<h4>$1</h4>');
  html = html.replace(/^### (.*)$/gm, '<h3>$1</h3>');
  html = html.replace(/^## (.*)$/gm, '<h2>$1</h2>');
  html = html.replace(/^# (.*)$/gm, '<h1>$1</h1>');
  // Bold / italic / inline code
  html = html.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
  html = html.replace(/\*([^*]+)\*/g, '<em>$1</em>');
  html = html.replace(/`([^`]+)`/g, '<code>$1</code>');
  // Links
  html = html.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" target="_blank">$1</a>');
  // Lists
  html = html.replace(/^(\s*)[-*] (.*)$/gm, '$1<li>$2</li>');
  html = html.replace(/(<li>[^<]*<\/li>\n?)+/g, m => '<ul>' + m + '</ul>');
  // Blockquote
  html = html.replace(/^&gt; (.*)$/gm, '<blockquote>$1</blockquote>');
  // Paragraphs (any line not starting with a tag)
  html = html.split(/\n\n+/).map(block => {
    if (/^\s*<(h\d|ul|pre|blockquote|li)/.test(block.trim())) return block;
    return '<p>' + block.replace(/\n/g, '<br>') + '</p>';
  }).join('\n');
  return html;
}
function htmlToMarkdown(html) {
  // Naive — strip tags. Good enough as a fallback.
  return String(html).replace(/<[^>]+>/g, '').replace(/\n{3,}/g, '\n\n').trim();
}
function wrapHtmlDoc(title, body) {
  return `<!DOCTYPE html><html><head><meta charset="utf-8"><title>${escapeHtml(title)}</title><style>body{font-family:'Cormorant Garamond',Georgia,serif;max-width:720px;margin:40px auto;padding:0 24px;line-height:1.7;color:#1a1410}h1,h2,h3{font-family:'Cinzel',serif;letter-spacing:0.05em;color:#2d1f0e}h2{font-size:18px;letter-spacing:0.15em;text-transform:uppercase;color:#c8621a;border-bottom:1px solid #b89a4a;padding-bottom:4px;margin-top:32px}code,pre{background:#f5efe6;padding:2px 6px;border-radius:3px;font-family:'JetBrains Mono',monospace;font-size:13px}pre{padding:12px;overflow-x:auto}blockquote{border-left:3px solid #b89a4a;padding-left:14px;color:#7a6e62;font-style:italic;margin:14px 0}a{color:#c8621a}</style></head><body>${body}</body></html>`;
}

