function expandAttrCode(field, value) {
  if (!value) return null;
  const dict = ATTR_VOCAB[field];
  if (!dict) return value;
  return dict[value] || value;
}

// ── CONTEXT-AWARE FIELD SELECTOR ─────────────────────────────────────────
// Given a panel prompt + a character, return ONLY the fields relevant to this
// panel. Skips hand fields if no hands featured; skips walking fields in still
// portraits; etc. This is the token-budget solution.
const PANEL_CONTEXT_RULES = [
  { keywords: ['hand', 'finger', 'grip', 'hold', 'pencil', 'fist', 'palm', 'reaching'],
    add_fields: ['hand_size', 'finger_shape', 'nail_style', 'hand_asymmetry'] },
  { keywords: ['walk', 'walking', 'run', 'running', 'stride', 'step', 'pace'],
    add_fields: ['walking_style', 'gait', 'foot_shape', 'center_of_gravity'] },
  { keywords: ['cry', 'tear', 'sad', 'grief', 'mourn'],
    add_fields: ['emotional_resting_face', 'expression_range', 'crying_style'] },
  { keywords: ['laugh', 'smile', 'grin', 'joy', 'happy'],
    add_fields: ['laugh_style', 'smile_type', 'dimples', 'teeth_structure'] },
  { keywords: ['angry', 'shout', 'yell', 'rage', 'fight'],
    add_fields: ['anger_expression', 'eyebrow_shape', 'jaw_when_tense'] },
  { keywords: ['close-up', 'closeup', 'extreme close', 'macro', 'face fills'],
    add_fields: ['skin_texture', 'eye_size', 'eyelash_type', 'lip_shape',
      'pore_detail', 'eye_asymmetry', 'micro_expressions'] },
  { keywords: ['silhouette', 'shadow', 'backlit', 'outline only'],
    add_fields: ['silhouette_type', 'shape_language', 'distinctive_silhouette_features'] },
  { keywords: ['back view', 'from behind', 'turning away'],
    add_fields: ['hair_back', 'back_silhouette', 'rear_costume_details'] },
  { keywords: ['old', 'aged', 'elderly', 'wrinkle'],
    add_fields: ['aging_details', 'wrinkles', 'age_appearance'] },
  { keywords: ['child', 'young', 'small'],
    add_fields: ['age_appearance', 'childhood_features', 'baby_fat'] }
];

function selectRelevantAttributesForRender(panelPrompt, data) {
  if (!data) return {};
  const lc = (panelPrompt || '').toLowerCase();
  // ALWAYS include Tier 1 core fields
  const alwaysInclude = ['name', 'age', 'age_band', 'face_shape', 'skin_tone',
    'hair', 'eye_shape', 'eye_color', 'silhouette_type', 'shape_language',
    'signature_costume', 'clothing_design', 'asymmetry_markers',
    'absolute_forbidden_changes', 'default_rest_pose'];
  const selected = {};
  for (const k of alwaysInclude) {
    if (data[k] != null) selected[k] = data[k];
  }
  // Then add context-triggered fields
  const triggered = new Set();
  for (const rule of PANEL_CONTEXT_RULES) {
    if (rule.keywords.some(kw => lc.includes(kw))) {
      rule.add_fields.forEach(f => triggered.add(f));
    }
  }
  for (const k of triggered) {
    if (data[k] != null) selected[k] = data[k];
  }
  return selected;
}

