    document.body.appendChild(inp);
    inp.onchange = async () => {
      const f = inp.files[0]; if (!f) return;
      const text = await f.text();
      try {
        const data = JSON.parse(text);
        if (data.canonical_name) {
          const id = slugify(data.canonical_name) + '_' + Date.now().toString(36);
          LIBRARY[id] = data;
          saveLibrary(); renderCharactersGrid(); renderCharStrip(); toast('Character imported', 'ok');
        } else if (typeof data === 'object') {
          // Maybe a library bundle
          let n = 0;
          for (const [k, v] of Object.entries(data)) if (v && v.canonical_name) { LIBRARY[k] = v; n++; }
          saveLibrary(); renderCharactersGrid(); renderCharStrip(); toast(`${n} characters imported`, 'ok');
        }
      } catch (e) { toast('Import failed: ' + e.message, 'error'); }
      document.body.removeChild(inp);
    };
