        status.textContent = `✓ Global style ACTIVE: "${(styleJson.art_style || 'custom').slice(0,40)}" · ${STATE.globalStyleRefDataUrls.length} ref images · applies to ALL categories`;
        status.style.color = 'var(--green)';
